import { useEffect, useMemo, useState } from 'react'
import { Link } from 'react-router-dom'
import { api } from '../api'
import type { Collection, FlowSummary, Repository, TagCount } from '../types'
import { formatRelative } from '../lib/flow'

type LibraryView = { kind: 'all' } | { kind: 'favorites' } | { kind: 'archived' } | { kind: 'collection'; id: string } | { kind: 'tag'; name: string }

export function Library() {
  const [flows, setFlows] = useState<FlowSummary[]>([])
  const [collections, setCollections] = useState<Collection[]>([])
  const [tags, setTags] = useState<TagCount[]>([])
  const [repos, setRepos] = useState<Repository[]>([])

  const [q, setQ] = useState('')
  const [debouncedQ, setDebouncedQ] = useState('')
  const [type, setType] = useState('')
  const [repo, setRepo] = useState('')
  const [view, setView] = useState<LibraryView>({ kind: 'all' })
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    const t = setTimeout(() => setDebouncedQ(q), 200)
    return () => clearTimeout(t)
  }, [q])

  const load = useMemo(
    () =>
      async (
        v: LibraryView,
        params: { q?: string; type?: string; repo?: string },
      ) => {
        try {
          let list = await api.listFlows({
            q: params.q,
            type: params.type,
            repo: params.repo,
            view: v.kind === 'favorites' ? 'favorites' : v.kind === 'archived' ? 'archived' : 'all',
          })
          if (v.kind === 'collection') {
            const col = collections.find((c) => c.id === v.id)
            const ids = new Set((col?.items ?? []).map((i) => i.flowId))
            list = list.filter((f) => ids.has(f.id))
          }
          if (v.kind === 'tag') {
            list = list.filter((f) => f.tags.includes(v.name))
          }
          setFlows(list)
          setError(null)
        } catch (e) {
          setError(String((e as Error).message ?? e))
        }
      },
    [collections],
  )

  useEffect(() => {
    api.collections().then(setCollections).catch(() => undefined)
    api.tags().then(setTags).catch(() => undefined)
    api.repositories().then(setRepos).catch(() => undefined)
  }, [])

  useEffect(() => {
    load(view, { q: debouncedQ || undefined, type: type || undefined, repo: repo || undefined })
  }, [view, debouncedQ, type, repo, load])

  const title =
    view.kind === 'all'
      ? 'All Flows'
      : view.kind === 'favorites'
        ? 'Favorites'
        : view.kind === 'archived'
          ? 'Archived'
          : view.kind === 'collection'
            ? collections.find((c) => c.id === view.id)?.name ?? 'Collection'
            : `#${view.name}`

  return (
    <div className="library">
      <aside className="lib-sidebar">
        <div className="lib-logo">
          <span className="lib-logo-mark">⇢</span> Flow Viewer
        </div>
        <nav className="lib-nav">
          <div className="lib-nav-section">
            <div className="lib-nav-title">Library</div>
            <button className={view.kind === 'all' ? 'on' : ''} onClick={() => setView({ kind: 'all' })}>
              All Flows
            </button>
            <button className={view.kind === 'favorites' ? 'on' : ''} onClick={() => setView({ kind: 'favorites' })}>
              ★ Favorites
            </button>
            <button className={view.kind === 'archived' ? 'on' : ''} onClick={() => setView({ kind: 'archived' })}>
              Archived
            </button>
          </div>
          <div className="lib-nav-section">
            <div className="lib-nav-title">Collections</div>
            {collections.map((c) => (
              <button
                key={c.id}
                className={view.kind === 'collection' && view.id === c.id ? 'on' : ''}
                onClick={() => setView({ kind: 'collection', id: c.id })}
              >
                {c.name}
                <span className="lib-count">{c.items.length}</span>
              </button>
            ))}
          </div>
          <div className="lib-nav-section">
            <div className="lib-nav-title">Tags</div>
            {tags.map((t) => (
              <button key={t.name} className={view.kind === 'tag' && view.name === t.name ? 'on' : ''} onClick={() => setView({ kind: 'tag', name: t.name })}>
                #{t.name}
                <span className="lib-count">{t.count}</span>
              </button>
            ))}
          </div>
        </nav>
      </aside>

      <main className="lib-main">
        <div className="lib-toolbar">
          <input
            className="lib-search"
            placeholder="Search flows, symbols, files…"
            value={q}
            onChange={(e) => setQ(e.target.value)}
            autoFocus
          />
          <select className="lib-select" value={type} onChange={(e) => setType(e.target.value)} title="Filter by flow type">
            <option value="">All types</option>
            <option value="http">HTTP</option>
            <option value="startup">Startup</option>
            <option value="async">Async</option>
            <option value="job">Job</option>
            <option value="ui">UI</option>
            <option value="other">Other</option>
          </select>
          <select className="lib-select" value={repo} onChange={(e) => setRepo(e.target.value)} title="Filter by repository">
            <option value="">All repositories</option>
            {repos.map((r) => (
              <option key={r.id} value={r.name}>
                {r.name}
              </option>
            ))}
          </select>
        </div>

        <div className="lib-results">
          <div className="lib-results-head">
            <span className="lib-results-title">{title}</span>
            <span className="lib-results-count">
              {flows.length} flow{flows.length === 1 ? '' : 's'}
            </span>
          </div>

          {error && <div className="lib-error">{error}</div>}

          {flows.length === 0 && !error && (
            <div className="lib-empty">
              <p>No flows match.</p>
              <p className="dim">
                Publish one from a coding agent: <code>POST /api/flows</code> — see README and{' '}
                <code>server/examples/publish-create-exporter.json</code>.
              </p>
            </div>
          )}

          <div className="flow-cards">
            {flows.map((f) => (
              <FlowCard
                key={f.id}
                f={f}
                onToggleFavorite={() =>
                  api.patchFlow(f.id, { isFavorite: !f.isFavorite }).then((updated) => setFlows((cur) => cur.map((x) => (x.id === f.id ? { ...x, ...updated } : x))))
                }
                onArchive={() =>
                  api.patchFlow(f.id, { isArchived: !f.isArchived }).then(() => load(view, { q: debouncedQ || undefined, type: type || undefined, repo: repo || undefined }))
                }
              />
            ))}
          </div>
        </div>
      </main>
    </div>
  )
}

function FlowCard({ f, onToggleFavorite, onArchive }: { f: FlowSummary; onToggleFavorite: () => void; onArchive: () => void }) {
  return (
    <Link className={`flow-card ${f.isFavorite ? 'fav' : ''}`} to={`/flow/${f.id}`}>
      <div className="fc-top">
        <span className="fc-name">{f.name}</span>
        <span className={`type-badge type-${f.type}`}>{f.type.toUpperCase()}</span>
        <span className="fc-spacer" />
        <span className="fc-stats">
          {f.fileCount} files · {f.regionCount} regions · v{f.latestVersion}
        </span>
        <button
          className={`fc-fav ${f.isFavorite ? 'on' : ''}`}
          title={f.isFavorite ? 'Unfavorite' : 'Favorite'}
          onClick={(e) => {
            e.preventDefault()
            onToggleFavorite()
          }}
        >
          {f.isFavorite ? '★' : '☆'}
        </button>
        <button
          className="fc-archive"
          title={f.isArchived ? 'Unarchive' : 'Archive'}
          onClick={(e) => {
            e.preventDefault()
            onArchive()
          }}
        >
          {f.isArchived ? '↩' : '⌫'}
        </button>
      </div>
      {f.description && <div className="fc-desc">{f.description}</div>}
      <div className="fc-bottom">
        {f.repository && (
          <span className="fc-repo" title={f.repository.url ?? ''}>
            {f.repository.name}:{f.branch ?? f.repository.branch ?? 'main'}
          </span>
        )}
        <span className="fc-tags">
          {f.tags.map((t) => (
            <span key={t} className="fc-tag">
              #{t}
            </span>
          ))}
        </span>
        <span className="fc-spacer" />
        <span className="fc-updated">{formatRelative(f.updatedAt)}</span>
      </div>
    </Link>
  )
}

import { HashRouter, Route, Routes, useParams, Navigate } from 'react-router-dom'
import { Library } from './components/Library'
import { Workspace } from './components/Workspace'

function FlowRoute() {
  const { flowId } = useParams()
  return <Workspace key={flowId} flowId={flowId ?? ''} />
}

export default function App() {
  return (
    <HashRouter>
      <Routes>
        <Route path="/" element={<Library />} />
        <Route path="/flow/:flowId" element={<FlowRoute />} />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </HashRouter>
  )
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { Link } from 'react-router-dom'
import { api } from '../api'
import type { FlowDetail, FlowNode, ViewMode } from '../types'
import { backwardReachable, filesById, nodesById, orderedNodes, pathNodes } from '../lib/flow'
import { FlowHeader } from './FlowHeader'
import { PathStrip } from './PathStrip'
import { Navigator } from './Navigator'
import { SourceView } from './SourceView'
import { GraphView } from './GraphView'
import { StatusLine } from './StatusLine'

interface HistEntry {
  nodeId: string | null
  fileId: string | null
  scrollLine: number | null
}

export function Workspace({ flowId }: { flowId: string }) {
  const [detail, setDetail] = useState<FlowDetail | null>(null)
  const [error, setError] = useState<string | null>(null)

  const [view, setView] = useState<ViewMode>('editor')
  const [activeNodeId, setActiveNodeId] = useState<string | null>(null)
  const [activeFileId, setActiveFileId] = useState<string | null>(null)
  const [tabs, setTabs] = useState<string[]>([])
  const [history, setHistory] = useState<HistEntry[]>([])
  const [future, setFuture] = useState<HistEntry[]>([])
  const [exitFilter, setExitFilter] = useState<string | null>(null)
  const [query, setQuery] = useState('')
  const [revealToken, setRevealToken] = useState(0)
  const [panelOpen, setPanelOpen] = useState(true)
  const [panelWidth, setPanelWidth] = useState(300)
  const [theme, setTheme] = useState<'dark' | 'light'>(() =>
    (localStorage.getItem('flow-theme') as 'dark' | 'light') ?? 'dark',
  )

  const scrollLineRef = useRef<number | null>(null)
  const panelResizeRef = useRef<{ startX: number; startW: number } | null>(null)

  // Theme
  useEffect(() => {
    document.documentElement.dataset.theme = theme
    localStorage.setItem('flow-theme', theme)
    document.dispatchEvent(new CustomEvent('flow-theme-change'))
  }, [theme])

  // Load flow
  useEffect(() => {
    let cancelled = false
    api
      .getFlow(flowId)
      .then((d) => {
        if (cancelled) return
        setDetail(d)
        // Open the entry node by default.
        const entry = d.nodes.filter((n) => n.kind === 'entry').sort((a, b) => a.sortOrder - b.sortOrder)[0]
        const target = entry ?? d.nodes.slice().sort((a, b) => a.sortOrder - b.sortOrder)[0]
        if (target) {
          setActiveNodeId(target.id)
          if (target.fileId) {
            setActiveFileId(target.fileId)
            setTabs([target.fileId])
          }
          setRevealToken(1)
        }
      })
      .catch((e) => setError(String(e.message ?? e)))
    return () => {
      cancelled = true
    }
  }, [flowId])

  const byId = useMemo(() => (detail ? nodesById(detail) : new Map<string, FlowNode>()), [detail])
  const files = useMemo(() => (detail ? filesById(detail) : new Map()), [detail])
  const ordered = useMemo(() => (detail ? orderedNodes(detail) : []), [detail])
  const path = useMemo(() => (detail ? pathNodes(detail) : []), [detail])

  // Exit-filter reachability
  const dimmedIds = useMemo(() => {
    if (!detail || !exitFilter) return null
    const exitNode = detail.nodes.find((n) => n.kind === 'exit' && n.exitStatus === exitFilter)
    if (!exitNode) return null
    const { nodes } = backwardReachable(detail.edges, exitNode.id)
    return nodes
  }, [detail, exitFilter])

  const pushHistory = useCallback(() => {
    const entry: HistEntry = {
      nodeId: activeNodeId,
      fileId: activeFileId,
      scrollLine: scrollLineRef.current,
    }
    setHistory((h) => [...h, entry])
    setFuture([])
  }, [activeNodeId, activeFileId])

  const navigate = useCallback(
    (nodeId: string, opts?: { history?: boolean; view?: ViewMode }) => {
      const node = byId.get(nodeId)
      if (!node) return
      if (opts?.history !== false) pushHistory()
      setActiveNodeId(nodeId)
      if (node.fileId) {
        setActiveFileId(node.fileId)
        setTabs((t) => (t.includes(node.fileId!) ? t : [...t, node.fileId!].slice(-10)))
      }
      if (opts?.view) setView(opts.view)
      setRevealToken((t) => t + 1)
    },
    [byId, pushHistory],
  )

  const restore = useCallback(
    (entry: HistEntry) => {
      setActiveNodeId(entry.nodeId)
      setActiveFileId(entry.fileId)
      if (entry.fileId && entry.nodeId) {
        setTabs((t) => (t.includes(entry.fileId!) ? t : [...t, entry.fileId!]))
      }
      // Reveal the node region (restores approximate position).
      const node = entry.nodeId ? byId.get(entry.nodeId) : null
      if (node && node.fileId && node.startLine) {
        scrollLineRef.current = node.startLine
      }
      setRevealToken((t) => t + 1)
    },
    [byId],
  )

  const goBack = useCallback(() => {
    if (history.length === 0) return
    const prev = history[history.length - 1]
    const cur: HistEntry = { nodeId: activeNodeId, fileId: activeFileId, scrollLine: scrollLineRef.current }
    setHistory(history.slice(0, -1))
    setFuture([...future, cur])
    restore(prev)
  }, [history, future, activeNodeId, activeFileId, restore])

  const goForward = useCallback(() => {
    if (future.length === 0) return
    const next = future[future.length - 1]
    const cur: HistEntry = { nodeId: activeNodeId, fileId: activeFileId, scrollLine: scrollLineRef.current }
    setFuture(future.slice(0, -1))
    setHistory([...history, cur])
    restore(next)
  }, [history, future, activeNodeId, activeFileId, restore])

  const stepIndex = activeNodeId ? ordered.findIndex((n) => n.id === activeNodeId) : -1
  const goNext = useCallback(() => {
    if (ordered.length === 0) return
    const i = stepIndex < 0 ? 0 : (stepIndex + 1) % ordered.length
    navigate(ordered[i].id)
  }, [ordered, stepIndex, navigate])
  const goPrev = useCallback(() => {
    if (ordered.length === 0) return
    const i = stepIndex < 0 ? 0 : (stepIndex - 1 + ordered.length) % ordered.length
    navigate(ordered[i].id)
  }, [ordered, stepIndex, navigate])

  const toggleExit = useCallback((_exitId: string, status: string) => {
    setExitFilter((cur) => (cur === status ? null : status || null))
  }, [])

  const fileSelect = useCallback(
    (fileId: string) => {
      // Selecting a tab opens its first flow step.
      const node = detail
        ? detail.nodes.filter((n) => n.fileId === fileId).sort((a, b) => a.sortOrder - b.sortOrder)[0]
        : null
      if (node) {
        navigate(node.id, { history: false })
      } else {
        pushHistory()
        setActiveFileId(fileId)
        setTabs((t) => (t.includes(fileId) ? t : [...t, fileId]))
      }
    },
    [detail, navigate, pushHistory],
  )

  const fileClose = useCallback(
    (fileId: string) => {
      setTabs((t) => {
        const next = t.filter((id) => id !== fileId)
        if (fileId === activeFileId && next.length > 0) {
          const fallback = next[next.length - 1]
          const node = detail
            ? detail.nodes.filter((n) => n.fileId === fallback).sort((a, b) => a.sortOrder - b.sortOrder)[0]
            : null
          if (node) setActiveNodeId(node.id)
          setActiveFileId(fallback)
        }
        return next
      })
    },
    [activeFileId, detail],
  )

  // Global keyboard shortcuts (when the Monaco editor is not focused).
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement | null
      if (target && (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA')) return
      if (target && target.closest('.monaco-editor')) return // editor handles its own keys
      const mod = e.ctrlKey || e.metaKey
      if (e.key === 'g' && !mod) {
        e.preventDefault()
        setView((v) => (v === 'editor' ? 'graph' : 'editor'))
      } else if (e.key === 'Escape') {
        setExitFilter(null)
      } else if (e.altKey && e.key === 'ArrowDown') {
        e.preventDefault()
        goNext()
      } else if (e.altKey && e.key === 'ArrowUp') {
        e.preventDefault()
        goPrev()
      } else if (mod && e.shiftKey && e.key === 'ArrowLeft') {
        e.preventDefault()
        goBack()
      } else if (mod && e.shiftKey && e.key === 'ArrowRight') {
        e.preventDefault()
        goForward()
      }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [goNext, goPrev, goBack, goForward])

  // Panel resize drag
  useEffect(() => {
    const onMove = (e: MouseEvent) => {
      const r = panelResizeRef.current
      if (!r) return
      const w = Math.min(520, Math.max(180, r.startW + (e.clientX - r.startX)))
      setPanelWidth(w)
    }
    const onUp = () => {
      panelResizeRef.current = null
      document.body.style.cursor = ''
    }
    window.addEventListener('mousemove', onMove)
    window.addEventListener('mouseup', onUp)
    return () => {
      window.removeEventListener('mousemove', onMove)
      window.removeEventListener('mouseup', onUp)
    }
  }, [])

  if (error) {
    return (
      <div className="ws-error">
        <p>Could not load flow: {error}</p>
        <Link to="/">← Back to flows</Link>
      </div>
    )
  }
  if (!detail) {
    return (
      <div className="ws-loading">
        <span className="spinner" /> Loading flow…
      </div>
    )
  }

  const activeNode = activeNodeId ? byId.get(activeNodeId) ?? null : null

  return (
    <div className="workspace">
      <FlowHeader
        detail={detail}
        view={view}
        query={query}
        onQuery={setQuery}
        onView={setView}
        onToggleFavorite={() =>
          api.patchFlow(flowId, { isFavorite: !detail.flow.isFavorite }).then((updated) => setDetail({ ...detail, flow: updated }))
        }
      />
      <PathStrip
        detail={detail}
        activeNodeId={activeNodeId}
        dimmedIds={dimmedIds}
        exitFilter={exitFilter}
        onNavigateNode={(id) => navigate(id)}
        onToggleExit={toggleExit}
      />
      <div className="ws-body">
        {panelOpen ? (
          <>
            <aside className="ws-navigator" style={{ width: panelWidth }}>
              <div className="nav-toolbar">
                <span className="nav-toolbar-title">Navigator</span>
                <span className="nav-toolbar-count">{path.length} steps · {detail.files.length} files</span>
                <button className="nav-collapse" title="Collapse panel" onClick={() => setPanelOpen(false)}>
                  ⇤
                </button>
              </div>
              <div className="nav-scroll">
                <Navigator
                  detail={detail}
                  activeNodeId={activeNodeId}
                  dimmedIds={dimmedIds}
                  query={query}
                  onNavigateNode={(id) => navigate(id)}
                />
              </div>
            </aside>
            <div
              className="ws-resizer"
              onMouseDown={(e) => {
                panelResizeRef.current = { startX: e.clientX, startW: panelWidth }
                document.body.style.cursor = 'col-resize'
              }}
            />
          </>
        ) : (
          <button className="ws-panel-expand" title="Show navigator" onClick={() => setPanelOpen(true)}>
            ⇥
          </button>
        )}
        <main className="ws-main">
          {view === 'editor' ? (
            <SourceView
              detail={detail}
              activeNode={activeNode}
              activeFileId={activeFileId}
              tabs={tabs}
              dimmedIds={dimmedIds}
              revealToken={revealToken}
              onNavigateNode={(id) => navigate(id)}
              onBack={goBack}
              onForward={goForward}
              onNext={goNext}
              onPrev={goPrev}
              onFileSelect={fileSelect}
              onFileClose={fileClose}
              onScrollLine={(l) => {
                scrollLineRef.current = l
              }}
            />
          ) : (
            <GraphView
              detail={detail}
              activeNodeId={activeNodeId}
              dimmedIds={dimmedIds}
              onNodeClick={(id) => navigate(id, { view: 'editor' })}
            />
          )}
        </main>
      </div>
      <StatusLine
        detail={detail}
        activeNodeId={activeNodeId}
        activeFileId={activeFileId}
        view={view}
        exitFilter={exitFilter}
        onClearExitFilter={() => setExitFilter(null)}
        theme={theme}
        onToggleTheme={() => setTheme((t) => (t === 'dark' ? 'light' : 'dark'))}
      />
    </div>
  )
}

import type { Collection, FlowDetail, FlowSummary, Repository, TagCount } from './types'

async function get<T>(path: string): Promise<T> {
  const res = await fetch(path)
  if (!res.ok) throw new Error(`${path} -> ${res.status}`)
  return res.json() as Promise<T>
}

async function send<T>(method: string, path: string, body?: unknown): Promise<T> {
  const res = await fetch(path, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  })
  if (!res.ok) {
    let message = `${res.status}`
    try {
      const j = await res.json()
      if (j?.error) message = j.error
    } catch {
      // ignore
    }
    throw new Error(message)
  }
  if (res.status === 204) return undefined as T
  return res.json() as Promise<T>
}

export interface FlowListParams {
  q?: string
  type?: string
  repo?: string
  tag?: string
  view?: 'all' | 'favorites' | 'archived'
}

export const api = {
  listFlows(p: FlowListParams = {}): Promise<FlowSummary[]> {
    const sp = new URLSearchParams()
    if (p.q) sp.set('q', p.q)
    if (p.type) sp.set('type', p.type)
    if (p.repo) sp.set('repo', p.repo)
    if (p.tag) sp.set('tag', p.tag)
    if (p.view === 'favorites') sp.set('favorite', '1')
    if (p.view === 'archived') sp.set('archived', '1')
    const qs = sp.toString()
    return get(`/api/flows${qs ? `?${qs}` : ''}`)
  },
  getFlow(id: string, version?: number): Promise<FlowDetail> {
    return get(`/api/flows/${id}${version ? `?version=${version}` : ''}`)
  },
  patchFlow(id: string, body: Record<string, unknown>): Promise<FlowDetail['flow']> {
    return send('PATCH', `/api/flows/${id}`, body)
  },
  deleteFlow(id: string): Promise<void> {
    return send('DELETE', `/api/flows/${id}`)
  },
  publishFlow(payload: unknown): Promise<{ id: string; version: number }> {
    return send('POST', '/api/flows', payload)
  },
  collections(): Promise<Collection[]> {
    return get('/api/collections')
  },
  tags(): Promise<TagCount[]> {
    return get('/api/tags')
  },
  repositories(): Promise<Repository[]> {
    return get('/api/repositories')
  },
}

